contract InvMutTest {
    C c;
    uint public callCount;
    address public lastFrom;
    address public lastTo;
    uint public lastValue;

    constructor(C _c) { c = _c; }

    function run(address[] memory tos, uint[] memory vs, uint amount) public payable {
        require(tos.length > 0);
        require(address(this).balance >= amount);
        callCount = 0;
        bool result = c.transfer(address(this), tos, vs);
        assert(result && callCount == tos.length && lastFrom == address(this));
    }

    fallback(bytes calldata data) external payable returns (bytes memory) {
        if (data.length == 100) {
            // transferFrom(address,address,uint256): selector + 3 words
            address from = address(uint160(uint(bytes32(data[4:36]))));
            address to = address(uint160(uint(bytes32(data[36:68]))));
            uint val = uint(bytes32(data[68:100]));
            lastFrom = from;
            lastTo = to;
            lastValue = val;
            callCount++;
            return abi.encode(true);
        }
        return abi.encode(false);
    }

    receive() external payable {}
}

