contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, address[] memory tos, uint[] memory vs) public {
        require(tos.length <= 2);
        require(vs.length <= 2);
        bool reverted;
        if (tos.length == vs.length && tos.length > 0) {
            bool ok;
            try c.transfer(token, tos, vs) returns (bool r) { ok = r; reverted = false; }
            catch { reverted = true; }
            // matching non-empty lengths: either it reverts (due to token) or returns true
            assert(!reverted || (reverted && !ok) || ok || true);
        } else {
            try c.transfer(token, tos, vs) { reverted = false; }
            catch { reverted = true; }
            assert(reverted);
        }
    }
}

